package netsec

// The helpers in this file build HPACK wire representations for tests. They
// are deliberately independent of the production parser so that malformed and
// fragmented streams can be generated byte by byte.

func testAppendInt(dst []byte, prefix uint8, value uint64, mask byte) []byte {
	limit := uint64(1<<prefix) - 1
	if value < limit {
		return append(dst, mask|byte(value))
	}
	dst = append(dst, mask|byte(limit))
	value -= limit
	for value >= 0x80 {
		dst = append(dst, byte(value)|0x80)
		value >>= 7
	}
	return append(dst, byte(value))
}

func testString(dst []byte, s string, huffman bool) []byte {
	var raw []byte
	if huffman {
		raw = HuffmanEncode(nil, s)
	} else {
		raw = []byte(s)
	}
	pos := len(dst)
	dst = testAppendInt(dst, 7, uint64(len(raw)), 0)
	if huffman {
		dst[pos] |= 0x80
	}
	return append(dst, raw...)
}

func testIndexed(dst []byte, index uint64) []byte {
	return testAppendInt(dst, 7, index, 0x80)
}

func testLiteralIncremental(dst []byte, name string, nameIndex uint64, value string, huffman bool) []byte {
	dst = testAppendInt(dst, 6, nameIndex, 0x40)
	if nameIndex == 0 {
		dst = testString(dst, name, false)
	}
	return testString(dst, value, huffman)
}

func testLiteralWithoutIndexing(dst []byte, name string, nameIndex uint64, value string, huffman bool) []byte {
	dst = testAppendInt(dst, 4, nameIndex, 0x00)
	if nameIndex == 0 {
		dst = testString(dst, name, false)
	}
	return testString(dst, value, huffman)
}

func testLiteralNeverIndexed(dst []byte, name string, nameIndex uint64, value string, huffman bool) []byte {
	dst = testAppendInt(dst, 4, nameIndex, 0x10)
	if nameIndex == 0 {
		dst = testString(dst, name, false)
	}
	return testString(dst, value, huffman)
}

func testTableSizeUpdate(dst []byte, size uint64) []byte {
	return testAppendInt(dst, 5, size, 0x20)
}

func concat(parts ...[]byte) []byte {
	var out []byte
	for _, p := range parts {
		out = append(out, p...)
	}
	return out
}

func headersFrame(streamID uint32, endHeaders, endStream bool, fragment []byte) Frame {
	var flags FrameFlags
	if endHeaders {
		flags |= FlagEndHeaders
	}
	if endStream {
		flags |= FlagEndStream
	}
	return Frame{Type: FrameHeaders, Flags: flags, StreamID: streamID, Payload: fragment}
}

func continuationFrame(streamID uint32, endHeaders bool, fragment []byte) Frame {
	var flags FrameFlags
	if endHeaders {
		flags |= FlagEndHeaders
	}
	return Frame{Type: FrameContinuation, Flags: flags, StreamID: streamID, Payload: fragment}
}
